def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    total_players = 1 + len(alive)
    guaranteed_units = int(supply // WATER_REQ)
    scarcity = guaranteed_units < total_players

    highest_prev = 0.0
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if prev and prev.get('bid') is not None:
            prev_bid = float(prev.get('bid', 0.0))
        if prev_bid > highest_prev:
            highest_prev = prev_bid
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= 700:
            rich_opp += 1

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if scarcity:
        danger += 2
    if urgent_opp >= 1:
        danger += 1
    if highest_prev >= 120:
        danger += 2
    elif highest_prev >= 85:
        danger += 1

    if danger >= 6:
        target = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
    elif danger >= 4:
        target = max(0.74 * DAILY_SALARY, highest_prev * 0.72 + 2.0)
    elif danger >= 2:
        target = max(0.48 * DAILY_SALARY, highest_prev * 0.45 + 1.5)
    else:
        target = 0.22 * DAILY_SALARY
        if scarcity:
            target = max(target, 0.34 * DAILY_SALARY)

    if day >= 8 and hp > 5 and no_water_days == 0:
        target *= 0.9

    if rich_opp >= 2 and scarcity and (hp <= 4 or no_water_days >= 1):
        target = max(target, highest_prev + 4.0, 0.88 * DAILY_SALARY)

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 0.25 * DAILY_SALARY
    elif hp > 2:
        reserve = 0.1 * DAILY_SALARY

    affordable = max(0.0, budget - reserve)
    bid = min(target, affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 0.95 * DAILY_SALARY))

    if not alive:
        bid = min(budget, 0.35 * DAILY_SALARY)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate trace
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Pressure estimate: if someone already bid high yesterday, they likely contest water again.
    # Use a small overbid margin to win without going to extremes.
    margin = 3.0

    # Supply pressure: with higher supply, we can afford a slightly lower bid.
    # With lower supply, we need to outbid.
    if supply <= MIN_SUPPLY + 0.5:
        supply_tier = 0  # tight
    elif supply >= MAX_SUPPLY - 0.5:
        supply_tier = 2  # ample
    else:
        supply_tier = 1

    # Base target: try to beat yesterday's highest if it was competitive.
    # Competitive threshold relates to salary scale.
    competitive_threshold = DAILY_SALARY * 0.85  # 76.5

    # If my hp is critical, prioritize survival even if it costs more.
    critical_hp = my_hp <= 2.5
    low_budget = my_budget <= DAILY_SALARY * 0.6

    # Estimate required water days risk: if already no-water several days, bid harder.
    hunger_factor = 0.0
    if my_no_water_days >= 2:
        hunger_factor = 1.0
    elif my_no_water_days == 1:
        hunger_factor = 0.5

    if highest_prev_bid >= competitive_threshold:
        # Contest: bid just above the highest, with tier-based adjustment.
        tier_adjust = 1.0 if supply_tier == 0 else (0.7 if supply_tier == 1 else 0.5)
        target = highest_prev_bid + margin * tier_adjust
    else:
        # Not strongly contested yesterday: bid around a mid level.
        mid = DAILY_SALARY * (0.55 if supply_tier == 1 else (0.65 if supply_tier == 0 else 0.5))
        # If second highest exists, slightly above it to secure.
        target = max(mid, second_prev_bid + 2.0)

    if critical_hp:
        target *= 1.15
    if low_budget:
        target *= 0.9
    if hunger_factor > 0:
        target *= (1.0 + 0.12 * hunger_factor)

    # Never exceed budget; also keep non-negative.
    bid = max(0.0, min(my_budget, target))

    # If supply is extremely low, ensure we bid at least a meaningful fraction.
    if supply <= MIN_SUPPLY + 0.5 and bid < DAILY_SALARY * 0.6:
        bid = min(my_budget, DAILY_SALARY * 0.75)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    base_bid = avg_opp_bid * 1.05
    if supply < 18:
        bid = min(my_status['budget'], max(base_bid, 110.0))
    elif supply > 22:
        bid = min(my_status['budget'], max(base_bid * 0.7, 60.0))
    else:
        bid = min(my_status['budget'], base_bid)

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], max(bid, 120.0))

    return float(bid)
